import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import {
  type FormEvent,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { saveSighting, updateSightingDoneness } from "@/lib/sighting-functions";
import {
  type CreateSighting,
  type CreateSightingInput,
  createSightingInputSchema,
  DONENESS_FAILURE_MESSAGE,
  DONENESS_VALUES,
  SAVE_FAILURE_MESSAGE,
  type Sighting,
  type UpdateSightingDoneness,
} from "@/lib/sightings";

export const Route = createFileRoute("/")({
  component: CapturePage,
});

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type LabelTime = {
  labelDate: string;
  labelTime: string;
};

const getCurrentDeviceTime = (): Date => new Date();
const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;
const STORE_OPENING_MINUTE = 9 * 60;
const STORE_CLOSING_MINUTE = 20 * 60;

function padTimePart(value: number): string {
  return value.toString().padStart(2, "0");
}

function getDeviceLabelTime(date: Date): LabelTime {
  return {
    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
  };
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = LABEL_TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function isOutsideStoreHours(labelMinute: number | undefined): boolean {
  return (
    labelMinute !== undefined &&
    (labelMinute < STORE_OPENING_MINUTE || labelMinute > STORE_CLOSING_MINUTE)
  );
}

function formatSavedLabelTime(sighting: Sighting): string {
  const date = new Date(`${sighting.labelDate}T12:00:00`);
  const hour = Math.floor(sighting.labelMinute / 60);
  const minute = sighting.labelMinute % 60;
  const time = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(2000, 0, 1, hour, minute));
  const formattedDate = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(date);

  return `Saved label time for ${formattedDate} at ${time}.`;
}

export function CapturePage(): ReactNode {
  const save = useServerFn(saveSighting);
  const updateDoneness = useServerFn(updateSightingDoneness);
  const saveSightingFromRoute: CreateSighting = async (input) => {
    return await save({ data: input });
  };
  const updateSightingDonenessFromRoute: UpdateSightingDoneness = async (
    input
  ) => {
    return await updateDoneness({ data: input });
  };

  return (
    <CaptureForm
      saveSighting={saveSightingFromRoute}
      updateSightingDoneness={updateSightingDonenessFromRoute}
    />
  );
}

export function CaptureForm({
  now = getCurrentDeviceTime,
  saveSighting,
  updateSightingDoneness,
}: Readonly<{
  now?: () => Date;
  saveSighting: CreateSighting;
  updateSightingDoneness?: UpdateSightingDoneness;
}>): ReactNode {
  const [labelTime, setLabelTime] = useState<LabelTime>();
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isSaving, setIsSaving] = useState(false);
  const [savedSighting, setSavedSighting] = useState<Sighting>();

  useEffect(() => {
    setLabelTime(getDeviceLabelTime(now()));
  }, [now]);

  if (savedSighting && updateSightingDoneness) {
    return (
      <SightingCompletion
        onDone={() => {
          setErrorMessage(undefined);
          setLabelTime(getDeviceLabelTime(now()));
          setSavedSighting(undefined);
        }}
        sighting={savedSighting}
        updateSightingDoneness={updateSightingDoneness}
      />
    );
  }

  if (!labelTime) {
    return (
      <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
        <header className="mb-8">
          <p className="font-medium text-muted-foreground text-sm">
            Chicken Tracking
          </p>
          <h1 className="mt-2 font-semibold text-4xl tracking-tight">
            Capture
          </h1>
          <p className="mt-2 text-muted-foreground">
            Record the label time exactly as printed.
          </p>
        </header>
        <Card aria-busy="true">
          <CardHeader>
            <CardTitle>Label time</CardTitle>
          </CardHeader>
          <CardContent>
            <output aria-live="polite">Preparing capture form…</output>
          </CardContent>
        </Card>
      </div>
    );
  }

  const labelMinute = labelTimeToMinute(labelTime.labelTime);
  const outsideStoreHours = isOutsideStoreHours(labelMinute);

  const handleSave = async (): Promise<void> => {
    if (isSaving) {
      return;
    }

    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const input: CreateSightingInput = {
      labelDate: labelTime.labelDate,
      labelMinute,
    };
    const validation = createSightingInputSchema.safeParse(input);
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    try {
      const result = await saveSighting(validation.data);

      if (!result.ok) {
        setErrorMessage(result.message);
        return;
      }

      setSavedSighting(result.sighting);
    } catch {
      setErrorMessage(SAVE_FAILURE_MESSAGE);
    } finally {
      setIsSaving(false);
    }
  };

  const handleSubmit = async (
    event: FormEvent<HTMLFormElement>
  ): Promise<void> => {
    event.preventDefault();
    await handleSave();
  };

  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Capture</h1>
        <p className="mt-2 text-muted-foreground">
          Record the label time exactly as printed.
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Label time</CardTitle>
        </CardHeader>
        <CardContent>
          <form
            aria-label="Capture label time"
            className="grid gap-6"
            noValidate
            onSubmit={handleSubmit}
          >
            <div className="grid gap-2">
              <Label htmlFor="label-time">Label time</Label>
              <Input
                aria-describedby={
                  outsideStoreHours ? "store-hours-warning" : undefined
                }
                className="h-16 text-3xl"
                id="label-time"
                onChange={(event) => {
                  setLabelTime((current) => {
                    if (!current) {
                      return current;
                    }

                    return { ...current, labelTime: event.target.value };
                  });
                }}
                required
                type="time"
                value={labelTime.labelTime}
              />
              {outsideStoreHours ? (
                <p
                  className="text-sm text-warning-foreground"
                  id="store-hours-warning"
                >
                  Outside store hours
                </p>
              ) : null}
            </div>
            <div className="grid gap-2">
              <Label htmlFor="label-date">Label date</Label>
              <Input
                id="label-date"
                onChange={(event) => {
                  setLabelTime((current) => {
                    if (!current) {
                      return current;
                    }

                    return { ...current, labelDate: event.target.value };
                  });
                }}
                required
                type="date"
                value={labelTime.labelDate}
              />
            </div>
            {errorMessage ? (
              <p
                aria-live="assertive"
                className="text-destructive text-sm"
                role="alert"
              >
                {errorMessage}
              </p>
            ) : null}
            {isSaving ? (
              <output aria-live="polite">Saving label time…</output>
            ) : null}
            <Button
              className="h-12 text-base"
              disabled={isSaving}
              type="submit"
            >
              Save label time
            </Button>
import { z } from "zod";

export const DONENESS_VALUES = ["light", "medium", "dark"] as const;
export type Doneness = (typeof DONENESS_VALUES)[number];

export const createSightingInputSchema = z.object({
  labelDate: z.iso.date(),
  labelMinute: z.int().min(0).max(1439),
});

export type CreateSightingInput = z.infer<typeof createSightingInputSchema>;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
export type Sighting = {
  createdAt: Date;
  doneness: Doneness | null;
  id: number;
  labelDate: string;
  labelMinute: number;
  updatedAt: Date;
};

export type CreateSightingResult =
  | { ok: true; sighting: Sighting }
  | { message: string; ok: false };

export type CreateSighting = (
  input: CreateSightingInput
) => Promise<CreateSightingResult>;

export const updateSightingDonenessInputSchema = z.object({
  doneness: z.enum(DONENESS_VALUES).nullable(),
  id: z.int().positive(),
});

export type UpdateSightingDonenessInput = z.infer<
  typeof updateSightingDonenessInputSchema
>;

export type UpdateSightingDonenessResult =
  | { ok: true; sighting: Sighting }
  | { kind: "not-found"; message: string; ok: false }
  | { kind: "unavailable"; message: string; ok: false };

export type UpdateSightingDoneness = (
  input: UpdateSightingDonenessInput
) => Promise<UpdateSightingDonenessResult>;

export const SAVE_FAILURE_MESSAGE =
  "Unable to save label time. Check your connection and try again.";

export const DONENESS_FAILURE_MESSAGE = "Unable to save doneness. Try again.";
import { eq } from "drizzle-orm";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";

import { db } from "@/lib/db";
import { type schema, sightings } from "@/lib/db/schema";
import {
  type CreateSighting,
  type CreateSightingInput,
  type CreateSightingResult,
  DONENESS_FAILURE_MESSAGE,
  SAVE_FAILURE_MESSAGE,
  type UpdateSightingDoneness,
  type UpdateSightingDonenessInput,
  type UpdateSightingDonenessResult,
} from "@/lib/sightings";

type Database = NodePgDatabase<typeof schema>;

export function createSightingOperations(database: Database): {
  create: CreateSighting;
  updateDoneness: UpdateSightingDoneness;
} {
  return {
    create: async (
      input: CreateSightingInput
    ): Promise<CreateSightingResult> => {
      try {
        const [record] = await database
          .insert(sightings)
          .values(input)
          .returning();

        if (!record) {
          return { message: SAVE_FAILURE_MESSAGE, ok: false };
        }

        return { ok: true, sighting: record };
      } catch {
        return { message: SAVE_FAILURE_MESSAGE, ok: false };
      }
    },
    updateDoneness: async (
      input: UpdateSightingDonenessInput
    ): Promise<UpdateSightingDonenessResult> => {
      try {
        const [record] = await database
          .update(sightings)
          .set({ doneness: input.doneness, updatedAt: new Date() })
          .where(eq(sightings.id, input.id))
          .returning();

        if (!record) {
          return {
            kind: "not-found",
            message: "This sighting is no longer available.",
            ok: false,
          };
        }

        return { ok: true, sighting: record };
      } catch {
        return {
          kind: "unavailable",
          message: DONENESS_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
  };
}

export const sightingOperations = createSightingOperations(db);
import { createServerFn } from "@tanstack/react-start";

import {
  createSightingInputSchema,
  updateSightingDonenessInputSchema,
} from "@/lib/sightings";

export const saveSighting = createServerFn({ method: "POST" })
  .inputValidator(createSightingInputSchema)
  .handler(async ({ data }) => {
    const { sightingOperations } = await import("@/lib/sightings.server");

    return sightingOperations.create(data);
  });

export const updateSightingDoneness = createServerFn({ method: "POST" })
  .inputValidator(updateSightingDonenessInputSchema)
  .handler(async ({ data }) => {
    const { sightingOperations } = await import("@/lib/sightings.server");

    return sightingOperations.updateDoneness(data);
  });
import "@testing-library/jest-dom/vitest";

import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { act } from "react";
import { hydrateRoot } from "react-dom/client";
import { renderToString } from "react-dom/server";
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  type CreateSighting,
  SAVE_FAILURE_MESSAGE,
  type UpdateSightingDoneness,
} from "@/lib/sightings";

const { mockSaveSighting, mockUseServerFn } = vi.hoisted(() => ({
  mockSaveSighting: vi.fn(),
  mockUseServerFn: vi.fn(),
}));

vi.mock("@tanstack/react-start", async (importOriginal) => ({
  ...(await importOriginal()),
  useServerFn: mockUseServerFn,
}));

import { CaptureForm, CapturePage } from "./app/index";

const DEFAULT_CLOCK = new Date(2026, 7, 11, 14, 5);
const SAVED_LABEL_TIME_MESSAGE =
  /Saved label time for August 11, 2026 at 8:00 AM/;
const COMPLETION_LABEL_TIME_MESSAGE =
  /Saved label time for August 11, 2026 at 2:05 PM/;

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
  vi.useRealTimers();
});

const createSavedSighting = () => ({
  createdAt: DEFAULT_CLOCK,
  doneness: null,
  id: 1,
  labelDate: "2026-08-11",
  labelMinute: 845,
  updatedAt: DEFAULT_CLOCK,
});

function renderCapture(
  saveSighting: CreateSighting,
  updateSightingDoneness: UpdateSightingDoneness = vi.fn()
): void {
  render(
    <CaptureForm
      now={() => DEFAULT_CLOCK}
      saveSighting={saveSighting}
      updateSightingDoneness={updateSightingDoneness}
    />
  );
}

describe("Capture", () => {
  it("does not read a server-local clock while rendering the hydration-safe pending state", () => {
    const unavailableServerClock = (): Date => {
      throw new Error("The device clock is only available in the browser.");
    };

    const html = renderToString(
      <CaptureForm now={unavailableServerClock} saveSighting={vi.fn()} />
    );

    expect(html).toContain("Preparing capture form");
    expect(html).not.toContain('type="time"');
  });

  it("defaults to the device's local date and minute", () => {
    renderCapture(vi.fn());

    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByLabelText("Label time")).toHaveValue("14:05");
  });

  it("hydrates the route with the client-local time after a midnight, month, and year boundary", async () => {
    vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
    vi.useFakeTimers();
    vi.setSystemTime(new Date(2026, 11, 31, 23, 59));
    mockUseServerFn.mockReturnValue(mockSaveSighting);

    const serverHtml = renderToString(<CapturePage />);
    const container = document.createElement("div");
    container.innerHTML = serverHtml;
    document.body.append(container);

    expect(container).toHaveTextContent("Preparing capture form");
    expect(container.querySelector('input[type="time"]')).toBeNull();

    vi.advanceTimersByTime(60_000);

    let root: ReturnType<typeof hydrateRoot> | undefined;
    await act(async () => {
      root = hydrateRoot(container, <CapturePage />);
      await Promise.resolve();
    });

    expect(screen.getByLabelText("Label date")).toHaveValue("2027-01-01");
    expect(screen.getByLabelText("Label time")).toHaveValue("00:00");

    await act(() => {
      root?.unmount();
    });
    vi.unstubAllGlobals();

    expect(screen.queryByLabelText("Label date")).toBeNull();
  });

  it("submits through the CapturePage server-function wiring", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(DEFAULT_CLOCK);
    mockUseServerFn.mockReturnValue(mockSaveSighting);
    mockSaveSighting.mockResolvedValue({
      ok: true,
      sighting: {
        createdAt: DEFAULT_CLOCK,
        doneness: null,
        id: 1,
        labelDate: "2026-08-11",
        labelMinute: 845,
        updatedAt: DEFAULT_CLOCK,
      },
    });

    render(<CapturePage />);

    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    fireEvent.submit(screen.getByRole("form", { name: "Capture label time" }));
    await Promise.resolve();

    expect(mockSaveSighting).toHaveBeenCalledWith({
      data: { labelDate: "2026-08-11", labelMinute: 845 },
    });
  });

  it("warns but allows a label time outside store hours", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: {
        createdAt: new Date("2026-08-11T19:05:00.000Z"),
        doneness: null,
        id: 1,
        labelDate: "2026-08-11",
        labelMinute: 480,
        updatedAt: new Date("2026-08-11T19:05:00.000Z"),
      },
    });
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "08:00" },
    });
    expect(screen.getByText("Outside store hours")).toBeTruthy();

    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(saveSighting).toHaveBeenCalledWith({
        labelDate: "2026-08-11",
        labelMinute: 480,
      });
    });
    await waitFor(() => {
      expect(screen.getByText(SAVED_LABEL_TIME_MESSAGE)).toBeTruthy();
    });
  });

  it("submits when Enter is pressed from a label field", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: {
        createdAt: new Date("2026-08-11T19:05:00.000Z"),
        doneness: null,
        id: 1,
        labelDate: "2026-08-11",
        labelMinute: 845,
        updatedAt: new Date("2026-08-11T19:05:00.000Z"),
      },
    });
    renderCapture(saveSighting);

    fireEvent.submit(screen.getByRole("form", { name: "Capture label time" }));

    await waitFor(() => {
      expect(saveSighting).toHaveBeenCalledWith({
        labelDate: "2026-08-11",
        labelMinute: 845,
      });
    });
  });

  it("blocks invalid input before save", () => {
    const saveSighting = vi.fn();
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2026-02-30" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    expect(screen.getByText("Enter a complete real date.")).toBeTruthy();
    expect(saveSighting).not.toHaveBeenCalled();
  });

  it("prevents duplicate saves while communicating progress", async () => {
    let resolveSave:
      | ((value: Awaited<ReturnType<CreateSighting>>) => void)
      | undefined;
    const saveSighting = vi.fn(
      () =>
        new Promise<Awaited<ReturnType<CreateSighting>>>((resolve) => {
          resolveSave = resolve;
        })
    );
    renderCapture(saveSighting);

    const saveButton = screen.getByRole("button", { name: "Save label time" });
    fireEvent.click(saveButton);
    fireEvent.click(saveButton);

    expect(saveSighting).toHaveBeenCalledTimes(1);
    expect(screen.getByRole("status")).toHaveTextContent("Saving label time");
    expect(saveButton).toBeDisabled();

    resolveSave?.({
      ok: false,
      message:
        "Unable to save label time. Check your connection and try again.",
    });
    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(
        "Unable to save label time"
      );
    });
  });

  it("keeps entered facts available after an initial save failure", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: false,
      message:
        "Unable to save label time. Check your connection and try again.",
    });
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2024-02-29" },
    });
    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "20:30" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toBeTruthy();
    });
    expect(screen.getByLabelText("Label date")).toHaveValue("2024-02-29");
    expect(screen.getByLabelText("Label time")).toHaveValue("20:30");
    expect(screen.queryByText("Sighting saved")).toBeNull();
  });

  it("recovers when the save request rejects", async () => {
    const saveSighting = vi
      .fn()
      .mockRejectedValue(new Error("Network unavailable"));
    renderCapture(saveSighting);

    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(SAVE_FAILURE_MESSAGE);
    });
    expect(
      screen.getByRole("button", { name: "Save label time" })
    ).toBeEnabled();
    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByLabelText("Label time")).toHaveValue("14:05");
  });

  it("shows full-screen completion only after label time is durably created", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: createSavedSighting(),
    });
    renderCapture(saveSighting);

    expect(screen.getByRole("heading", { name: "Capture" })).toBeTruthy();
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

// @vitest-environment node

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

import { drizzle } from "drizzle-orm/node-postgres";
import { Client } from "pg";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { schema } from "@/lib/db/schema";

const databaseUrl = process.env.DATABASE_URL;
const migrationPath = resolve(
  process.cwd(),
  "drizzle/20260811072733_early_luke_cage/migration.sql"
);

if (databaseUrl) {
  describe("sighting persistence", () => {
    let client: Client;

    beforeEach(async () => {
      client = new Client({ connectionString: databaseUrl });
      await client.connect();
      await client.query('DROP TABLE IF EXISTS "sightings"');

      const migration = await readFile(migrationPath, "utf8");
      for (const statement of migration.split("--> statement-breakpoint")) {
        await client.query(statement);
      }
    });

    afterEach(async () => {
      await client.end();
    });

    it("applies the baseline constraints and permits duplicate label facts", async () => {
      const database = drizzle(databaseUrl, { schema });
      const { createSightingOperations } = await import("./sightings.server");
      const operations = createSightingOperations(database);

      try {
        const first = await operations.create({
          labelDate: "2026-08-11",
          labelMinute: 845,
        });
        const duplicate = await operations.create({
          labelDate: "2026-08-11",
          labelMinute: 845,
        });

        expect(first).toMatchObject({
          ok: true,
          sighting: {
            doneness: null,
            labelDate: "2026-08-11",
            labelMinute: 845,
          },
        });
        expect(duplicate).toMatchObject({
          ok: true,
          sighting: { labelDate: "2026-08-11", labelMinute: 845 },
        });
        expect(
          first.ok && duplicate.ok && duplicate.sighting.id
        ).toBeGreaterThan(first.ok ? first.sighting.id : 0);

        await expect(
          client.query(
            "insert into sightings (label_date, label_minute) values ('2026-08-11', 1440)"
          )
        ).rejects.toMatchObject({ code: "23514" });
        await expect(
          client.query(
            "insert into sightings (label_date, label_minute, doneness) values ('2026-08-11', 0, 'raw')"
          )
        ).rejects.toMatchObject({ code: "23514" });
      } finally {
        await database.$client.end();
      }
    });

    it("creates the required representation and only its initial recency index", async () => {
      const columns = await client.query<{ column_name: string }>(
        "select column_name from information_schema.columns where table_name = 'sightings' order by ordinal_position"
      );
      const indexes = await client.query<{ indexname: string }>(
        "select indexname from pg_indexes where tablename = 'sightings' order by indexname"
      );

      expect(columns.rows.map((column) => column.column_name)).toEqual([
        "id",
        "label_date",
        "label_minute",
        "doneness",
        "created_at",
        "updated_at",
      ]);
      expect(indexes.rows.map((index) => index.indexname)).toEqual([
        "sightings_pkey",
        "sightings_recent_idx",
      ]);
    });

    it("updates only nullable doneness and advances the update instant", async () => {
      const database = drizzle(databaseUrl, { schema });
      const { createSightingOperations } = await import("./sightings.server");
      const operations = createSightingOperations(database);

      try {
        const created = await operations.create({
          labelDate: "2024-02-29",
          labelMinute: 480,
        });
        expect(created.ok).toBe(true);
        if (!created.ok) {
          return;
        }

        await new Promise((resolve) => setTimeout(resolve, 10));
        const enriched = await operations.updateDoneness({
          doneness: "dark",
          id: created.sighting.id,
        });

        expect(enriched).toMatchObject({
          ok: true,
          sighting: {
            doneness: "dark",
            id: created.sighting.id,
            labelDate: "2024-02-29",
            labelMinute: 480,
          },
        });
        expect(
          enriched.ok && enriched.sighting.updatedAt.getTime()
        ).toBeGreaterThan(created.sighting.updatedAt.getTime());

        const cleared = await operations.updateDoneness({
          doneness: null,
          id: created.sighting.id,
        });
        expect(cleared).toMatchObject({
          ok: true,
          sighting: { doneness: null, id: created.sighting.id },
        });
      } finally {
        await database.$client.end();
      }
    });

    it("returns a structured result when the targeted sighting is missing", async () => {
      const database = drizzle(databaseUrl, { schema });
      const { createSightingOperations } = await import("./sightings.server");
      const operations = createSightingOperations(database);

      try {
        await expect(
          operations.updateDoneness({ doneness: "light", id: 99 })
        ).resolves.toEqual({
          kind: "not-found",
          message: "This sighting is no longer available.",
          ok: false,
        });
      } finally {
        await database.$client.end();
      }
    });
  });
